Script.ScriptCode:
/*
var dt = new Date();
  //dt.setFullYear(d.year,d.month-1,d.day);
var current = new Date();
var limit = new Date();
f('Hid_LENGTH_CH').set(current.getDate()+14);


var d = new Date(f("LENGTH_CHx1").item('1').get(),f("LENGTH_CHx2").item('1').get(),f("LENGTH_CHx3").item('1').get());


  var dt = new Date();
  dt.setFullYear(d.year,d.month-1,d.day);
  var current = new Date();
  var limit = new Date();
  limit.setDate(current.getDate()+14)
if (dt.valueOf() > limit.valueOf())
   {
