*/
var day = parseInt(f("LENGTH_CHx1").item('1').get(), 10);
var month = parseInt(f("LENGTH_CHx2").item('1').get(), 10);
var year = parseInt(f("LENGTH_CHx3").item('1').valueLabel(), 10);

// Build dt
var dt = new Date(year, month - 1, day);
dt.setHours(0,0,0,0);

// Current date
var current = new Date();
current.setHours(0,0,0,0);

// Limit (+14 days)
var limit = new Date(current);
limit.setDate(limit.getDate() - 14);

// ✅ Format for DATE question (must be YYYY-MM-DD)
var dt_iso = dt.getFullYear() + "-" +
             ("0" + (dt.getMonth()+1)).slice(-2) + "-" +
             ("0" + dt.getDate()).slice(-2);

var limit_iso = limit.getFullYear() + "-" +
                ("0" + (limit.getMonth()+1)).slice(-2) + "-" +
                ("0" + limit.getDate()).slice(-2);

// ✅ Set into DATE-type questions
f('LENGTH_CH_DATE').set(dt_iso);
f('LENGTH_CH_LIMIT').set(limit_iso);

// Logic
if (dt <= limit) {
    f('Hid_LENGTH_CH').set(1);
} else {
    f('Hid_LENGTH_CH').set(2);
}

if (GetSurveyChannel() == "Cawi" && f('Mode').any('1')) {
    Redirect(GetRespondentUrl("gLENGTH_CH", false), true);
}
else {
    Redirect(GetCatiRespondentUrl("gLENGTH_CH"));
}

