var qid = CurrentForm();
var mno  = "";
var flg = false;

//Extract new no.
if (f(qid).any("2")) {
    mno = f(qid + "_2_other").get();
}

//validate new no.
if (mno.charAt(0) == "0" && mno.length == 10 && IsNumeric(mno)) {
    flg = true;
}

if (!flg && f(qid).any("2")) {
    RaiseError();
    ClearErrorMessage();
