//Programmer: update with each requested survey version change with relaunchment.
f('SurveyChanges').set('4')

//Set total quota
f('q_Total').set('1')

//f('wave').set('1') - LinA gets populated by automation

//DO NOT CHANGE BELOW
//LinA will need to add l variable into panel database first
/*if (GetRespondentValue("l") == null || GetRespondentValue("l") == "")
{
    SetRespondentValue("l","3081")
    f("l").set("3081")
}*/

if (f('total_attempt_count').toBoolean()==false) {
    f('total_attempt_count').set('1')
}
else {
    f('total_attempt_count').set(f('total_attempt_count').toNumber()+1)
}

if (Request.QueryString.item("iuser1") != null) {
    f("iuser1").set(Request.QueryString.item("iuser1"))
}
else {
    if (GetSurveyChannel() == "Cati") {
        f("iuser1").set('2') //CATI
    }
    else {
        f("iuser1").set('4') //online email
    }
}

var entrymodelist = f("EntryMode").domainValues();
var iuser1 = f("iuser1").get();
// Check if iuser1 exists in the EntryMode code list
var exists = entrymodelist.includes(iuser1);
if (f('total_attempt_count')==1) {   
    if (exists) {
        f("EntryMode").set(f("iuser1"))
    }
    f("FinishMode").set(f("EntryMode"))
    f("Cumulative_EntryMode").set(f("EntryMode"))
}
else {
    if (exists) {
        f("FinishMode").set(f("iuser1"))
        f("Cumulative_EntryMode").set(f("Cumulative_EntryMode").get()+","+f("FinishMode"))        
