//f('End_Time').set(ausDate)


const int_date = new Date(f('End_Time'))
//in DD/MM/YYYY format
var int_dd = int_date.getDate().toString()
if (int_dd.length == 1) { int_dd = "0" + int_dd }
var int_mm = (int_date.getMonth()+1).toString()
if (int_mm.length == 1) { int_mm = "0" + int_mm }
var int_yyyy = int_date.getFullYear().toString()
f('IntDate').set( int_dd + "/" + int_mm + "/" + int_yyyy)


var options = { hour12: false, hourCycle: 'h23', hour: '2-digit', minute: '2-digit', second: '2-digit' };
var currentTime = ausDate.toLocaleTimeString('en-AU', options);
f('IntTime').set(currentTime);

// INCENTIVE AWARD (BOTH FOOD FREQUENCY AND GASTRO SURVEY)

// If the panellist completed the survey and they are not dummy
if ((GetExtendedStatus() == 13 || GetExtendedStatus() == 32) && f('dummy_sample').get() == 'N') {
    // Add credit to the panellist for compeletes
    // By setting PanelistId to out-of-range (-1), we award credit to the CURRENT panelist
    SetPanelistCredit(Number(GetPoints()), PointsLabel(), -1, f('recordid').get());
}

// set redirect fail indicator to 0
f('redirect_fail').set("0")

/* --------------------------

ADDITIONAL INCENTIVE AWARD (FOOD FREQUENCY SURVEY ONLY)

PLEASE READ - CONFIGURING THIS SCRIPT: 

Please carefully set the following values below before use:

- enabled
- index
- additional_incentive_amount
- min_n_sections

Then, please also review the receive_incentive condition below

*/

// enabled
var enabled = true // set to true to enable this additional incentive!

// index
var index = 1; // 1 means this is the first additional incentive, use 2 for the second and so on. Should match index in script title.

// amount
var additional_incentive_amount = 5; // Set to required amount in dollars

// min_n_sections
var min_n_sections = 2 // Set to the min value of n_sections required to qualify for this incentive

// receive_incentive condition
var completed_main = (GetExtendedStatus() == 13 || GetExtendedStatus() == 32)
var is_not_dummy = f('dummy_sample').get() == 'N'
var exceeds_min_n_sections = f('n_sections').get() >= min_n_sections
var receive_incentive = completed_main && is_not_dummy && exceeds_min_n_sections

function AdditionalPointsLabel(amount, section) {
    return "Additional " + section
        + " (" + f('src_job_id').get() + ") completed, awarded "
        + amount + " dollars.";
}

// DO NOT EDIT BELOW THIS LINE ------
if (enabled && receive_incentive) {

    additional_points_label = AdditionalPointsLabel(String(additional_incentive_amount), 'section ' + String(index));
    sectionId = f('recordid').get() + "_" + String(index + 1);

    // Add credit to the panellist for compeletes
    // By setting PanelistId to out-of-range (-1), we award credit to the CURRENT panelist
    SetPanelistCredit(Number(additional_incentive_amount), additional_points_label, -1, sectionId);

    // If the status is currently null, we need to set the status to avoid pending incentive
    if (!GetStatus()) {
      SetStatus('Incomplete');
    }
}

// panellist should not end up here - to be removed in the future after LinA Forsta migration
// set redirect fail indicator to 0
if (GetSurveyChannel()=="Cawi") {
    f('redirect_fail').set("1")
}
